// function toNumber(str) mein string do
// Agar string nahi: null
// Agar numeric nahi hai: NaN
// Warna parseFloat return karo

solution:
function toNumber(str) {
  if (typeof str !== "string") return null
  const num = parseFloat(str)
  if (Number.isNaN(num)) return NaN
  return num
}
